package com.medtrack.inventory.service;
import com.medtrack.batch.entity.*; import com.medtrack.inventory.dto.*; import com.medtrack.inventory.entity.*; import com.medtrack.inventory.repository.InventoryBalanceRepository; import com.medtrack.shared.exception.*; import com.medtrack.user.entity.User; import com.medtrack.user.repository.UserRepository; import com.medtrack.warehouse.entity.*; import com.medtrack.warehouse.repository.WarehouseRepository; import java.time.LocalDate; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*;
@Service public class FefoAllocationEngine {private final InventoryBalanceRepository balances;private final WarehouseRepository warehouses;private final UserRepository users;private final DoubleEntryLedgerService ledger;private final CriticalAuditService audit; public FefoAllocationEngine(InventoryBalanceRepository b,WarehouseRepository w,UserRepository u,DoubleEntryLedgerService l,CriticalAuditService a){balances=b;warehouses=w;users=u;ledger=l;audit=a;}
 @Transactional(isolation=Isolation.READ_COMMITTED) public FefoAllocationResponse allocate(UUID actorId,FefoAllocationRequest request){Warehouse warehouse=activeWarehouse(request.warehouseId());User actor=actor(actorId);List<InventoryBalance> candidates=new ArrayList<>(balances.lockFefoCandidates(request.medicineId(),warehouse.getId()));candidates.sort(Comparator.comparing((InventoryBalance b)->b.getBatch().getExpiryDate()).thenComparing(b->b.getBatch().getId()));int remaining=request.requiredQuantity();List<InventoryBalance> selected=new ArrayList<>();List<Integer> quantities=new ArrayList<>();for(InventoryBalance balance:candidates){if(remaining==0)break;int quantity=Math.min(remaining,balance.getAvailableQuantity());selected.add(balance);quantities.add(quantity);remaining-=quantity;}if(remaining!=0)throw new DomainException("INSUFFICIENT_AVAILABLE_STOCK","Insufficient available stock for requested FEFO allocation");return reserve(actor,warehouse,selected,quantities,"FEFO allocation",false,null);}
 @Transactional(isolation=Isolation.READ_COMMITTED) public FefoAllocationResponse override(UUID actorId,FefoOverrideRequest request){Warehouse warehouse=activeWarehouse(request.warehouseId());User actor=actor(actorId);InventoryBalance balance=balances.lockByWarehouseAndBatch(warehouse.getId(),request.batchId()).orElseThrow(()->new NotFoundException("Inventory balance"));Batch batch=balance.getBatch();if(batch.getStatus()!=BatchStatus.ACTIVE||batch.getExpiryDate().isBefore(LocalDate.now()))throw new DomainException("BATCH_NOT_ALLOCATABLE","Only active, unexpired batches may be manually allocated");if(balance.getAvailableQuantity()<request.quantity())throw new DomainException("INSUFFICIENT_AVAILABLE_STOCK","Insufficient available stock for manual allocation");return reserve(actor,warehouse,List.of(balance),List.of(request.quantity()),"FEFO manual override: "+request.overrideReason(),true,request.overrideReason());}
 private FefoAllocationResponse reserve(User actor,Warehouse warehouse,List<InventoryBalance> selected,List<Integer> quantities,String description,boolean overridden,String reason){List<InventoryLedgerLine> lines=new ArrayList<>();List<FefoAllocationResponse.Allocation> output=new ArrayList<>();for(int i=0;i<selected.size();i++){InventoryBalance balance=selected.get(i);int quantity=quantities.get(i);lines.add(InventoryLedgerLine.physical(balance.getBatch(),warehouse,LedgerDirection.DEBIT,quantity,balance,-quantity,quantity,0));lines.add(InventoryLedgerLine.offset(balance.getBatch(),AccountType.AUDIT_SURPLUS_OFFSET,LedgerDirection.CREDIT,quantity));balance.reserve(quantity);output.add(new FefoAllocationResponse.Allocation(balance.getBatch().getId(),balance.getBatch().getBatchNumber(),quantity,balance.getBatch().getExpiryDate().toString()));}InventoryJournalEntry journal=ledger.record(JournalEntryType.STOCK_ADJUSTMENT,"FEFO_ALLOCATION",UUID.randomUUID(),actor,description,lines);String detail="{\"overridden\":"+overridden+(reason==null?"":",\"reason\":\""+escape(reason)+"\"")+"}";audit.record(actor.getId(),overridden?"FEFO_OVERRIDE":"FEFO_ALLOCATION","INVENTORY_JOURNAL_ENTRY",journal.getId(),detail);return new FefoAllocationResponse(List.copyOf(output));} private Warehouse activeWarehouse(UUID id){Warehouse warehouse=warehouses.findById(id).orElseThrow(()->new NotFoundException("Warehouse"));if(warehouse.getStatus()!=WarehouseStatus.ACTIVE)throw new DomainException("WAREHOUSE_INACTIVE","Warehouse is inactive");return warehouse;} private User actor(UUID id){return users.findById(id).orElseThrow(()->new NotFoundException("User"));} private String escape(String s){return s.replace("\\","\\\\").replace("\"","\\\"");}}
